ui.customCSS:
.WidgetSelection_SelectionChoice {
   background-color: #D2B48C;
   border: 1px solid var(--static-accent, #654321);
   color: var(--static-accent, #654321);
   
}
.MainHeader_AppLogoImage {
   height: 40px;
}

.AdaptiveCard_Content {
  background-color: #ffffff; /* your desired color */
  
}

.MessageBody_MessageBodyContainer:has(.AdaptiveCard_Content:only-child) {
   background-color: #ffffff;
   padding: 5px;
}

.ac-container.ac-adaptiveCard {
   border: 2px solid #ffffff !important;
}

.ac-input:not(.ac-toggleInput).ac-input-validation-failed {
    background-color: #ffffff;
    border-color: #000000;
}

.ac-input:not(.ac-toggleInput) {
   border-radius: 5px;
}

.ac-input-container:has(.ac-input-validation-failed) + .ac-textBlock {
   font-size: 0.8rem !important;
}
.ac-textBlock {
   color: #451400 !important;
}
.ac-textRun {
   color: #451400 !important;
}

.ac-pushButton.style-positive, .ac-pushButton-disabled.style-positive {
   color: #000000 !important;
   /*background-color: #ffffff !important;*/
   border: none !important;
   border-radius: 50px !important;
   padding: 6px 50px !important;
   width: fit-content !important;
   margin: 0 auto !important;
   display: block !important;
   box-shadow: none !important;
}
